import React, { useState, useEffect } from 'react';
import axios from 'axios';
import CryptoJS from 'crypto-js';
import './OrderPage.scss';
import { useLocation } from 'react-router-dom';

const OrderPage = () => {
    const location = useLocation();
    const selectedDoctors = location.state?.selectedDoctors || [];

    const [cities, setCities] = useState([]);
    const [warehouses, setWarehouses] = useState([]);
    const [selectedCity, setSelectedCity] = useState('');
    const [selectedWarehouse, setSelectedWarehouse] = useState('');
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        address: '',
        phone: '',
    });

    const API_KEY = '4b43b81dfa23afae2dbf44851510a110'; // API Нової Пошти
    const LIQPAY_PUBLIC_KEY = 'sandbox_XysjrvqzETT1mDbWisgJCbUYm1mgh7x2NRJhIa2W'; // Ваш LiqPay Public Key
    const LIQPAY_PRIVATE_KEY = 'sandbox_XysjrvqzETT1mDbWisgJCbUYm1mgh7x2NRJhIa2W'; // Ваш LiqPay Private Key

    useEffect(() => {
        axios
            .post('https://api.novaposhta.ua/v2.0/json/', {
                apiKey: API_KEY,
                modelName: 'Address',
                calledMethod: 'getCities',
                methodProperties: {},
            })
            .then((response: any) => {
                if (response.data.success) {
                    setCities(response.data.data);
                } else {
                    console.error('Error fetching cities:', response.data.errors);
                }
            })
            .catch((error) => {
                console.error('Error fetching cities:', error);
            });
    }, []);

    useEffect(() => {
        if (selectedCity) {
            axios
                .post('https://api.novaposhta.ua/v2.0/json/', {
                    apiKey: API_KEY,
                    modelName: 'Address',
                    calledMethod: 'getWarehouses',
                    methodProperties: {
                        CityRef: selectedCity,
                    },
                })
                .then((response: any) => {
                    if (response.data.success) {
                        setWarehouses(response.data.data);
                    } else {
                        console.error('Error fetching warehouses:', response.data.errors);
                    }
                })
                .catch((error) => {
                    console.error('Error fetching warehouses:', error);
                });
        }
    }, [selectedCity]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        setFormData({ ...formData, [name]: value });
    };

    const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        if (validateForm()) {
            console.log('Form Data:', { ...formData, selectedCity, selectedWarehouse });
            alert('Order submitted successfully!');
        }
    };

    const validateForm = () => {
        const { name, email, phone } = formData;
        if (!name.trim() || !email.trim() || !phone.trim() || !selectedCity || !selectedWarehouse) {
            alert('Please fill in all the fields!');
            return false;
        }
        return true;
    };

    const handleLiqPayPayment = () => {
        // Створення параметрів платежу
        const paymentData = {
            public_key: LIQPAY_PUBLIC_KEY,
            version: '3',
            action: 'pay',
            amount: '1000', // Сума оплати
            currency: 'UAH',
            description: 'Оплата за лікарів',
            order_id: `order_${Date.now()}`,
            sandbox: '1', // Тестовий режим
        };

        // Кодування та створення підпису
        const base64Data = btoa(JSON.stringify(paymentData));
        const signature = CryptoJS.enc.Base64.stringify(
            CryptoJS.SHA1(LIQPAY_PRIVATE_KEY + base64Data + LIQPAY_PRIVATE_KEY)
        );

        // Перенаправлення на LiqPay
        const form = document.createElement('form');
        form.action = 'https://www.liqpay.ua/api/3/checkout';
        form.method = 'POST';
        form.target = '_blank';

        const dataInput = document.createElement('input');
        dataInput.type = 'hidden';
        dataInput.name = 'data';
        dataInput.value = base64Data;

        const signatureInput = document.createElement('input');
        signatureInput.type = 'hidden';
        signatureInput.name = 'signature';
        signatureInput.value = signature;

        form.appendChild(dataInput);
        form.appendChild(signatureInput);
        document.body.appendChild(form);
        form.submit();
        form.remove();
    };

    return (
        <div className="order-page">
            <h1>Order Form</h1>

            <div className="selected-doctors">
                <h2>Selected Doctors</h2>
                <ul>
                    {selectedDoctors.map((doctor: any) => (
                        <li key={doctor.id}>{doctor.doctor.name}</li>
                    ))}
                </ul>
            </div>

            <form onSubmit={handleSubmit}>
                <div className="form-group">
                    <label htmlFor="name">Name</label>
                    <input
                        id="name"
                        name="name"
                        type="text"
                        value={formData.name}
                        onChange={handleInputChange}
                        placeholder="Ваня Степанюк"
                    />
                </div>
                <div className="form-group">
                    <label htmlFor="email">Email</label>
                    <input
                        id="email"
                        name="email"
                        type="email"
                        value={formData.email}
                        onChange={handleInputChange}
                        placeholder="stepan@gmail.com"
                    />
                </div>
                <div className="form-group">
                    <label htmlFor="phone">Phone</label>
                    <input
                        id="phone"
                        name="phone"
                        type="text"
                        value={formData.phone}
                        onChange={handleInputChange}
                        placeholder="0992223344"
                    />
                </div>

                <button type="submit">Submit Order</button>
            </form>

            <button onClick={handleLiqPayPayment} className="liqpay-button">
                Pay with LiqPay
            </button>
        </div>
    );
};

export default OrderPage;
